starter.css:
.top { display: flex; justify-content: space-between; align-items: center; padding-block-end: 8px; border-block-end: 1px solid #ddd; }
.logo { font-weight: 700; }
.links { display: flex; gap: 12px; }
.title { font-size: 1.75rem; font-weight: 700; margin: 16px 0 8px; }
h2, h4 { font-size: 1.2rem; margin: 16px 0 4px; }
h3, h5 { font-size: 1rem; margin: 8px 0 2px; }
.bottom { margin-block-start: 24px; font-size: 0.875rem; color: #555; }

